#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StoredAllowance {
    pub allowance: Allowance,
    pub payment_method: PaymentMethod,
    pub billing_address: Option<Address>,
    pub used: bool,
    pub created_at: DateTime<Utc>,
    pub idempotency_key: Option<String>,
}

#[async_trait]
pub trait Storage: Send + Sync {
    async fn store_vault_token(
        &self,
        token_id: &str,
        stored: &StoredAllowance,
    ) -> Result<(), AppError>;

    async fn get_vault_token(&self, token_id: &str) -> Result<Option<StoredAllowance>, AppError>;

    async fn mark_vault_token_used(&self, token_id: &str) -> Result<bool, AppError>;

    async fn store_idempotency_key(
        &self,
        key: &str,
        token_id: &str,
        ttl_seconds: u64,
    ) -> Result<(), AppError>;

    async fn get_idempotency_key(&self, key: &str) -> Result<Option<String>, AppError>;
}

use std::sync::Arc;

use redis::{AsyncCommands, Client};

use super::{Storage, StoredAllowance};
use crate::errors::AppError;

pub struct RedisStorage {
    client: Client,
}

impl RedisStorage {
    pub fn new(redis_url: &str) -> Result<Self, AppError> {
        let client = Client::open(redis_url)
            .map_err(|e| AppError::ProcessingError(format!("Failed to connect to Redis: {}", e)))?;
        Ok(Self { client })
    }

    fn vault_key(token_id: &str) -> String {
        format!("vault:{}", token_id)
    }

    fn idempotency_key(key: &str) -> String {
        format!("idempotency:{}", key)
    }
}

#[async_trait::async_trait]
impl Storage for RedisStorage {
    async fn store_vault_token(
        &self,
        token_id: &str,
        stored: &StoredAllowance,
    ) -> Result<(), AppError> {
        let mut conn = self
            .client
            .get_multiplexed_async_connection()
            .await
            .map_err(|e| AppError::RedisError(e))?;

        let key = Self::vault_key(token_id);
        let value = serde_json::to_string(stored)?;

        // Calculate TTL based on expires_at
        let now = chrono::Utc::now();
        let ttl_seconds = if stored.allowance.expires_at > now {
            (stored.allowance.expires_at - now).num_seconds().max(1) as u64
        } else {
            60u64 // Minimum 60 seconds if already expired
        };

        redis::cmd("SETEX")
            .arg(&key)
            .arg(ttl_seconds)
            .arg(&value)
            .query_async::<_, ()>(&mut conn)
            .await
            .map_err(|e| AppError::RedisError(e))?;

        Ok(())
    }

    async fn get_vault_token(&self, token_id: &str) -> Result<Option<StoredAllowance>, AppError> {
        let mut conn = self
            .client
            .get_multiplexed_async_connection()
            .await
            .map_err(|e| AppError::RedisError(e))?;

        let key = Self::vault_key(token_id);
        let value: Option<String> = conn.get(&key).await.map_err(|e| AppError::RedisError(e))?;

        match value {
            Some(json_str) => {
                let stored: StoredAllowance = serde_json::from_str(&json_str)?;
                Ok(Some(stored))
            }
            None => Ok(None),
        }
    }

    async fn mark_vault_token_used(&self, token_id: &str) -> Result<bool, AppError> {
        let mut conn = self
            .client
            .get_multiplexed_async_connection()
            .await
            .map_err(|e| AppError::RedisError(e))?;

        let key = Self::vault_key(token_id);

        // Get current TTL to preserve it
        let ttl: i64 = conn.ttl(&key).await.unwrap_or(3600);

        let value: Option<String> = conn.get(&key).await.map_err(|e| AppError::RedisError(e))?;

        match value {
            Some(json_str) => {
                let mut stored: StoredAllowance = serde_json::from_str(&json_str)?;

                if stored.used {
                    return Ok(false); // Already used
                }

                stored.used = true;
                let new_value = serde_json::to_string(&stored)?;

                redis::cmd("SETEX")
                    .arg(&key)
                    .arg(ttl.max(1) as u64)
                    .arg(&new_value)
                    .query_async::<_, ()>(&mut conn)
                    .await
                    .map_err(|e| AppError::RedisError(e))?;

                Ok(true)
            }
            None => Ok(false),
        }
    }

    async fn store_idempotency_key(
        &self,
        key: &str,
        token_id: &str,
        ttl_seconds: u64,
    ) -> Result<(), AppError> {
        let mut conn = self
            .client
            .get_multiplexed_async_connection()
            .await
            .map_err(|e| AppError::RedisError(e))?;

        let redis_key = Self::idempotency_key(key);

        redis::cmd("SETEX")
            .arg(&redis_key)
            .arg(ttl_seconds)
            .arg(token_id)
            .query_async::<_, ()>(&mut conn)
            .await
            .map_err(|e| AppError::RedisError(e))?;

        Ok(())
    }

    async fn get_idempotency_key(&self, key: &str) -> Result<Option<String>, AppError> {
        let mut conn = self
            .client
            .get_multiplexed_async_connection()
            .await
            .map_err(|e| AppError::RedisError(e))?;

        let redis_key = Self::idempotency_key(key);
        let value: Option<String> = conn.get(&redis_key).await.map_err(|e| AppError::RedisError(e))?;

        Ok(value)
    }
}

pub type StorageRef = Arc<dyn Storage>;

use actix_web::{web, HttpRequest, HttpResponse};
use chrono::Utc;
use tracing::info;
use uuid::Uuid;

use crate::errors::AppError;
use crate::models::{DelegatePaymentRequest, DelegatePaymentResponse};
use crate::storage::StoredAllowance;
use crate::validation::card::validate_payment_method;
use crate::AppState;

pub async fn delegate_payment(
    state: web::Data<AppState>,
    req: HttpRequest,
    body: web::Json<DelegatePaymentRequest>,
) -> Result<HttpResponse, AppError> {
    let request = body.into_inner();

    // Extract headers
    let idempotency_key = req
        .headers()
        .get("Idempotency-Key")
        .and_then(|v| v.to_str().ok())
        .map(|s| s.to_string());

    let api_key = req
        .headers()
        .get("Authorization")
        .and_then(|v| v.to_str().ok())
        .map(|s| s.to_string());

    // Validate API key presence (basic check)
    if api_key.is_none() {
        return Err(AppError::InvalidRequest {
            message: "Missing Authorization header".to_string(),
            param: None,
        });
    }

    // Check idempotency
    if let Some(ref key) = idempotency_key {
        if let Some(existing_token) = state.storage.get_idempotency_key(key).await? {
            // Return existing token
            if let Some(stored) = state.storage.get_vault_token(&existing_token).await? {
                return Ok(HttpResponse::Created().json(DelegatePaymentResponse {
                    id: existing_token,
                    created: stored.created_at,
                    metadata: stored.payment_method.metadata.clone(),
                }));
            }
        }
    }

    // Validate allowance reason
    match request.allowance.reason {
        crate::models::AllowanceReason::OneTime => {}
    }

    // Validate currency format (ISO-4217 lowercase)
    if !request.allowance.currency.chars().all(|c| c.is_ascii_lowercase()) {
        return Err(AppError::InvalidRequest {
            message: "Currency must be lowercase ISO-4217 format".to_string(),
            param: Some("allowance.currency".to_string()),
        });
    }

    // Validate merchant_id length
    if request.allowance.merchant_id.len() > 256 {
        return Err(AppError::InvalidRequest {
            message: "Merchant ID must be at most 256 characters".to_string(),
            param: Some("allowance.merchant_id".to_string()),
        });
    }

    // Validate expiry is in the future
    let now = Utc::now();
    if request.allowance.expires_at <= now {
        return Err(AppError::InvalidRequest {
            message: "Expiry must be in the future".to_string(),
            param: Some("allowance.expires_at".to_string()),
        });
    }

    // Validate payment method
    validate_payment_method(&request.payment_method)?;

    // Generate vault token
    let token_id = format!("vt_{}", Uuid::new_v4());
    info!("Creating vault token: {} for merchant: {}", token_id, request.allowance.merchant_id);

    // Store the allowance data
    let stored = StoredAllowance {
        allowance: request.allowance,
        payment_method: request.payment_method,
        billing_address: request.billing_address,
        used: false,
        created_at: now,
        idempotency_key: idempotency_key.clone(),
    };

    state.storage.store_vault_token(&token_id, &stored).await?;

    // Store idempotency key if provided
    if let Some(key) = idempotency_key {
        // Store for 24 hours
        state.storage.store_idempotency_key(&key, &token_id, 86400).await?;
    }

    // Build response
    let response = DelegatePaymentResponse {
        id: token_id,
        created: stored.created_at,
        metadata: request.metadata,
    };

    Ok(HttpResponse::Created().json(response))
}

use actix_web::{web, HttpResponse};
use chrono::Utc;
use tracing::info;

use crate::errors::AppError;
use crate::models::{ValidatePaymentRequest, ValidatePaymentResponse};
use crate::AppState;

pub async fn validate_payment(
    state: web::Data<AppState>,
    body: web::Json<ValidatePaymentRequest>,
) -> Result<HttpResponse, AppError> {
    let request = body.into_inner();

    info!(
        "Validating payment for token: {}, amount: {} {}",
        request.vault_token, request.amount, request.currency
    );

    // Fetch the stored allowance
    let stored = match state.storage.get_vault_token(&request.vault_token).await? {
        Some(s) => s,
        None => {
            return Ok(HttpResponse::Ok().json(ValidatePaymentResponse {
                valid: false,
                vault_token: Some(request.vault_token),
                message: Some("Vault token not found".to_string()),
                code: Some("invalid_token".to_string()),
            }));
        }
    };

    // Check if token is expired
    let now = Utc::now();
    if stored.allowance.expires_at <= now {
        return Ok(HttpResponse::Ok().json(ValidatePaymentResponse {
            valid: false,
            vault_token: Some(request.vault_token),
            message: Some("Vault token has expired".to_string()),
            code: Some("token_expired".to_string()),
        }));
    }

    // Check if token is already used (one_time restriction)
    if stored.used {
        return Ok(HttpResponse::Ok().json(ValidatePaymentResponse {
            valid: false,
            vault_token: Some(request.vault_token),
            message: Some("Vault token has already been used".to_string()),
            code: Some("token_used".to_string()),
        }));
    }

    // Validate amount <= max_amount
    if request.amount > stored.allowance.max_amount {
        return Ok(HttpResponse::Ok().json(ValidatePaymentResponse {
            valid: false,
            vault_token: Some(request.vault_token),
            message: Some(format!(
                "Amount {} exceeds maximum allowed {}",
                request.amount, stored.allowance.max_amount
            )),
            code: Some("amount_exceeded".to_string()),
        }));
    }

    // Validate currency match
    if request.currency != stored.allowance.currency {
        return Ok(HttpResponse::Ok().json(ValidatePaymentResponse {
            valid: false,
            vault_token: Some(request.vault_token),
            message: Some(format!(
                "Currency mismatch: expected {}, got {}",
                stored.allowance.currency, request.currency
            )),
            code: Some("currency_mismatch".to_string()),
        }));
    }

    // Validate merchant_id match
    if request.merchant_id != stored.allowance.merchant_id {
        return Ok(HttpResponse::Ok().json(ValidatePaymentResponse {
            valid: false,
            vault_token: Some(request.vault_token),
            message: Some("Merchant ID does not match allowance".to_string()),
            code: Some("merchant_mismatch".to_string()),
        }));
    }

    // Validate checkout_session_id match
    if request.checkout_session_id != stored.allowance.checkout_session_id {
        return Ok(HttpResponse::Ok().json(ValidatePaymentResponse {
            valid: false,
            vault_token: Some(request.vault_token),
            message: Some("Checkout session ID does not match allowance".to_string()),
            code: Some("session_mismatch".to_string()),
        }));
    }

    // All validations passed - mark token as used
    let marked = state.storage.mark_vault_token_used(&request.vault_token).await?;

    if !marked {
        // Token was used between our read and write (race condition)
        return Ok(HttpResponse::Ok().json(ValidatePaymentResponse {
            valid: false,
            vault_token: Some(request.vault_token),
            message: Some("Vault token has already been used".to_string()),
            code: Some("token_used".to_string()),
        }));
    }

    info!("Payment validated successfully for token: {}", request.vault_token);

    Ok(HttpResponse::Ok().json(ValidatePaymentResponse {
        valid: true,
        vault_token: Some(request.vault_token),
        message: Some("Payment validated".to_string()),
        code: None,
    }))
}

use chrono::Datelike;

use crate::errors::AppError;
use crate::models::payment_method::PaymentMethod;

/// Validate card number using Luhn algorithm
pub fn validate_card_number(number: &str) -> Result<(), AppError> {
    // Remove any spaces or dashes
    let cleaned: String = number.chars().filter(|c| c.is_ascii_digit()).collect();

    if cleaned.len() < 13 || cleaned.len() > 19 {
        return Err(AppError::InvalidCard {
            message: "Card number must be between 13 and 19 digits".to_string(),
            param: Some("payment_method.number".to_string()),
        });
    }

    // Luhn algorithm
    let mut sum = 0;
    let mut alternate = false;

    for c in cleaned.chars().rev() {
        let mut n = c.to_digit(10).unwrap();
        if alternate {
            n *= 2;
            if n > 9 {
                n -= 9;
            }
        }
        sum += n;
        alternate = !alternate;
    }

    if sum % 10 != 0 {
        return Err(AppError::InvalidCard {
            message: "Card number failed Luhn validation".to_string(),
            param: Some("payment_method.number".to_string()),
        });
    }

    Ok(())
}

/// Validate expiry month and year
pub fn validate_expiry(exp_month: Option<&str>, exp_year: Option<&str>) -> Result<(), AppError> {
    let month_str = match exp_month {
        Some(m) => m,
        None => return Ok(()), // Optional field
    };

    let year_str = match exp_year {
        Some(y) => y,
        None => return Ok(()), // Optional field
    };

    // Parse month
    let month: u32 = month_str.parse().map_err(|_| AppError::InvalidCard {
        message: "Invalid expiry month".to_string(),
        param: Some("payment_method.exp_month".to_string()),
    })?;

    if month < 1 || month > 12 {
        return Err(AppError::InvalidCard {
            message: "Expiry month must be between 01 and 12".to_string(),
            param: Some("payment_method.exp_month".to_string()),
        });
    }

    // Parse year
    let year: i32 = year_str.parse().map_err(|_| AppError::InvalidCard {
        message: "Invalid expiry year".to_string(),
        param: Some("payment_method.exp_year".to_string()),
    })?;

    if year_str.len() != 4 {
        return Err(AppError::InvalidCard {
            message: "Expiry year must be 4 digits".to_string(),
            param: Some("payment_method.exp_year".to_string()),
        });
    }

    // Check if card is expired
    let now = chrono::Utc::now();
    let current_year = now.year();
    let current_month = now.month() as i32;

    if year < current_year || (year == current_year && month < current_month as u32) {
        return Err(AppError::InvalidCard {
            message: "Card has expired".to_string(),
            param: Some("payment_method.exp_year".to_string()),
        });
    }

    Ok(())
}

/// Validate CVC (3-4 digits)
pub fn validate_cvc(cvc: Option<&str>) -> Result<(), AppError> {
    if let Some(cvc_str) = cvc {
        if cvc_str.len() < 3 || cvc_str.len() > 4 {
            return Err(AppError::InvalidCard {
                message: "CVC must be 3 or 4 digits".to_string(),
                param: Some("payment_method.cvc".to_string()),
            });
        }
        if !cvc_str.chars().all(|c| c.is_ascii_digit()) {
            return Err(AppError::InvalidCard {
                message: "CVC must contain only digits".to_string(),
                param: Some("payment_method.cvc".to_string()),
            });
        }
    }
    Ok(())
}

/// Validate IIN (6 digits max)
pub fn validate_iin(iin: Option<&str>) -> Result<(), AppError> {
    if let Some(iin_str) = iin {
        if iin_str.len() > 6 {
            return Err(AppError::InvalidCard {
                message: "IIN must be at most 6 digits".to_string(),
                param: Some("payment_method.iin".to_string()),
            });
        }
        if !iin_str.chars().all(|c| c.is_ascii_digit()) {
            return Err(AppError::InvalidCard {
                message: "IIN must contain only digits".to_string(),
                param: Some("payment_method.iin".to_string()),
            });
        }
    }
    Ok(())
}

/// Validate display_last4 (4 digits max)
pub fn validate_last4(last4: Option<&str>) -> Result<(), AppError> {
    if let Some(last4_str) = last4 {
        if last4_str.len() > 4 {
            return Err(AppError::InvalidCard {
                message: "Last 4 must be at most 4 digits".to_string(),
                param: Some("payment_method.display_last4".to_string()),
            });
        }
    }
    Ok(())
}

/// Validate full payment method
pub fn validate_payment_method(pm: &PaymentMethod) -> Result<(), AppError> {
    // Validate type must be "card"
    if pm.payment_type != "card" {
        return Err(AppError::InvalidRequest {
            message: "Payment method type must be 'card'".to_string(),
            param: Some("payment_method.type".to_string()),
        });
    }

    // Validate card number
    validate_card_number(&pm.number)?;

    // Validate expiry
    validate_expiry(pm.exp_month.as_deref(), pm.exp_year.as_deref())?;

    // Validate CVC if provided
    validate_cvc(pm.cvc.as_deref())?;

    // Validate IIN if provided
    validate_iin(pm.iin.as_deref())?;

    // Validate last4 if provided
    validate_last4(pm.display_last4.as_deref())?;

    Ok(())
}

